#!/usr/bin/env python3

import requests
import json

def test_hourly_endpoint():
    try:
        url = "http://localhost:8000/analytics/hourly-activity"
        print(f"Testing: {url}")

        response = requests.get(url)
        print(f"Status Code: {response.status_code}")
        print(f"Headers: {response.headers}")

        if response.status_code == 200:
            data = response.json()
            print(f"Response JSON: {json.dumps(data, indent=2)}")

            if data.get('activity'):
                print(f"Found {len(data['activity'])} activity records")
                for i, record in enumerate(data['activity'][:3]):
                    print(f"  Record {i+1}: {record}")
            else:
                print("No activity data found")

            print(f"Query time: {data.get('query_time_ms', 'unknown')}ms")
        else:
            print(f"Error response: {response.text}")

    except Exception as e:
        print(f"Request failed: {e}")

if __name__ == "__main__":
    test_hourly_endpoint()

